/**
 * The Java-sourced per-state block property table, keyed by Bedrock block state - the server's
 * identity. Generated by `utils/generate/generate-block-properties.ts` from the Java 26.3 jar dump
 * golden, flattened through the block mapping: for each Bedrock state the table holds the property
 * row of the Java states that map onto it. Bedrock-only blocks with no Java source are listed in
 * {@link BEDROCK_ONLY_BLOCKS} and have no row; the engine keeps its own values for them. The
 * reviewed collapse disagreements are listed in {@link BLOCK_PROPERTY_CONFLICTS}.
 */
import blockPropertiesJson from './tables/blockProperties.json';

/** The Java-sourced properties of one Bedrock block state. */
export interface BedrockBlockProperties {
    /** Java destroy time; `-1` marks the unbreakable blocks (bedrock, barriers, portals). */
    readonly hardness: number;
    /** Java explosion resistance; bedrock is 3600000, obsidian 1200, stone 6. */
    readonly blastResistance: number;
    /** Ground friction: 0.6 for almost everything, 0.98 for ice, 0.989 for blue ice. */
    readonly friction: number;
    /** Emitted light, 0 to 15. */
    readonly lightEmission: number;
    /** How much light the block swallows, 0 to 15. */
    readonly lightDampening: number;
    /** Whether breaking without the right tool yields nothing. */
    readonly requiresCorrectTool: boolean;
    /** Whether the block receives random ticks (crops grow, ice melts, fire spreads). */
    readonly randomTick: boolean;
    /** How a piston treats the block: `push_pull`, `immoveable`, `popped`, `block` or `ignore`. */
    readonly pushReaction: string;
    /** Fire's odds of igniting the block, 0 for the fireproof. */
    readonly igniteOdds: number;
    /** Fire's odds of consuming the block once lit. */
    readonly burnOdds: number;
}

interface BlockRow {
    base: BedrockBlockProperties;
    stateOverrides?: Record<string, Partial<BedrockBlockProperties>>;
}

interface Conflict {
    bedrock: string;
    field: string;
    kept: number | string | boolean;
    keptSource: string;
    other: number | string | boolean;
    otherSource: string;
}

interface BlockPropertiesTable {
    javaVersion: string;
    bedrockVersion: string;
    blocks: Record<string, BlockRow>;
    bedrockOnly: string[];
    conflicts: Conflict[];
}

// The generated table is parsed JSON; the generator guarantees this shape.
const table = blockPropertiesJson as unknown as BlockPropertiesTable;

/**
 * Bedrock palette blocks no Java block state maps onto: the Education Edition chemistry set, the
 * world-editing blocks (`allow`, `deny`, `border_block`), the deprecated palette entries and the
 * other Bedrock-only identifiers. The table has no row for them, so a lookup returns `undefined`
 * and the caller keeps its own values rather than receiving a silent default.
 */
export const BEDROCK_ONLY_BLOCKS: ReadonlySet<string> = new Set(table.bedrockOnly);

/**
 * The reviewed flattening disagreements: Bedrock states whose Java sources did not agree on a
 * property, each kept value chosen by the rule the generator documents. All of them come from
 * Java properties Bedrock does not represent - piston extension, leaf distance, bamboo stage.
 */
export const BLOCK_PROPERTY_CONFLICTS: readonly Readonly<Conflict>[] = table.conflicts;

/** The version pair the property table was flattened from. */
export const BLOCK_PROPERTY_VERSIONS = {
    javaVersion: table.javaVersion,
    bedrockVersion: table.bedrockVersion
} as const;

/** A Bedrock state value as the engine holds it; booleans travel as 0 and 1 in the palette. */
type StateValue = string | number | boolean;

const matches = (stateKey: string, states: Readonly<Record<string, StateValue>>): boolean =>
    stateKey.split(',').every((pair) => {
        const separator = pair.indexOf('=');
        const property = pair.slice(0, separator);
        const value = pair.slice(separator + 1);
        const held = states[property];
        if (held === undefined) return false;
        return String(typeof held === 'boolean' ? Number(held) : held) === value;
    });

/**
 * The Java-sourced properties of a Bedrock block state, or `undefined` for a block with no Java
 * source (see {@link BEDROCK_ONLY_BLOCKS}).
 *
 * Without `states`, the answer is the block's base row: the value the majority of its states
 * share, which for every property but the handful of per-state overrides is the value of all of
 * them. With `states`, any override matching the given values is folded in - a lit candle's light,
 * an extended piston's missing base.
 * @param {string} name - The namespaced Bedrock block identifier, such as `minecraft:stone`.
 * @param {Readonly<Record<string, StateValue>>} [states] - The state's values, when the caller has them.
 * @returns {BedrockBlockProperties | undefined} The property row, or `undefined` with no Java source.
 * @example
 * ```typescript
 * bedrockBlockPropertiesOf('minecraft:blue_ice')?.friction; // 0.989
 * bedrockBlockPropertiesOf('minecraft:element_1'); // undefined
 * ```
 */
export const bedrockBlockPropertiesOf = (
    name: string,
    states?: Readonly<Record<string, StateValue>>
): BedrockBlockProperties | undefined => {
    const row = table.blocks[name];
    if (row === undefined) return undefined;
    if (states === undefined || row.stateOverrides === undefined) return row.base;

    let merged = row.base;
    for (const [stateKey, override] of Object.entries(row.stateOverrides)) {
        if (matches(stateKey, states)) merged = { ...merged, ...override };
    }
    return merged;
};
